template:
struct Package {
    weight: u32,
}

impl Package {
    fn cost(⟦selfparam⟧) -> u32 {
        self.weight * ⟦rate⟧
    }
}

fn main() {
    let p = Package { weight: 2 };
    println!("{} then {}", p.cost(), p.cost());
}

tests:
#[test]
fn costs_twice() {
    let p = Package { weight: 2 };
    assert_eq!(p.cost(), 6);
    assert_eq!(p.cost(), 6);
}
